CREATE DATABASE IF NOT EXISTS bgmi_esports_arena CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE bgmi_esports_arena;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS announcements;DROP TABLE IF EXISTS scores;DROP TABLE IF EXISTS registration_players;DROP TABLE IF EXISTS payments;DROP TABLE IF EXISTS registrations;DROP TABLE IF EXISTS tournaments;DROP TABLE IF EXISTS players;DROP TABLE IF EXISTS admins;
SET FOREIGN_KEY_CHECKS=1;
CREATE TABLE admins(admin_id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,username VARCHAR(60) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,is_active TINYINT(1) DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE players(player_id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(100) NOT NULL,email VARCHAR(190) UNIQUE NOT NULL,phone VARCHAR(20) NOT NULL,password_hash VARCHAR(255) NOT NULL,is_active TINYINT(1) DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE tournaments(tournament_id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(140) NOT NULL,short_label VARCHAR(40) NOT NULL DEFAULT 'BATTLE READY',description TEXT NOT NULL,rules TEXT,mode ENUM('Squad TPP','Squad FPP','Solo TPP','Duo TPP') NOT NULL DEFAULT 'Squad TPP',tournament_date DATETIME NOT NULL,registration_deadline DATETIME NOT NULL,entry_fee DECIMAL(10,2) NOT NULL DEFAULT 0,prize_pool DECIMAL(12,2) NOT NULL DEFAULT 0,max_teams INT UNSIGNED NOT NULL DEFAULT 32,status ENUM('upcoming','open','live','completed','cancelled') NOT NULL DEFAULT 'upcoming',created_by INT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(created_by) REFERENCES admins(admin_id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE registrations(registration_id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,registration_code VARCHAR(30) UNIQUE NOT NULL,tournament_id INT UNSIGNED NOT NULL,player_id INT UNSIGNED NOT NULL,team_name VARCHAR(80) NOT NULL,captain_uid VARCHAR(20) NOT NULL,status ENUM('pending_payment','payment_review','pending_review','confirmed','rejected','cancelled') NOT NULL DEFAULT 'pending_payment',admin_note VARCHAR(500),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_player_team(player_id,tournament_id,team_name),FOREIGN KEY(tournament_id) REFERENCES tournaments(tournament_id) ON DELETE RESTRICT,FOREIGN KEY(player_id) REFERENCES players(player_id) ON DELETE RESTRICT,INDEX(status)) ENGINE=InnoDB;
CREATE TABLE registration_players(registration_player_id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,registration_id INT UNSIGNED NOT NULL,player_name VARCHAR(100) NOT NULL,bgmi_uid VARCHAR(20) NOT NULL,in_game_name VARCHAR(100) NOT NULL,role ENUM('Captain','Player','Substitute') NOT NULL DEFAULT 'Player',FOREIGN KEY(registration_id) REFERENCES registrations(registration_id) ON DELETE CASCADE,UNIQUE KEY uq_reg_uid(registration_id,bgmi_uid)) ENGINE=InnoDB;
CREATE TABLE payments(payment_id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,registration_id INT UNSIGNED UNIQUE NOT NULL,amount DECIMAL(10,2) NOT NULL,currency CHAR(3) NOT NULL DEFAULT 'INR',status ENUM('created','payment_review','verified','failed','not_required','refunded') NOT NULL DEFAULT 'created',transaction_reference VARCHAR(100) UNIQUE NULL,gateway_order_id VARCHAR(120),gateway_payment_id VARCHAR(120),gateway_signature VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,verified_at DATETIME NULL,FOREIGN KEY(registration_id) REFERENCES registrations(registration_id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE scores(score_id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tournament_id INT UNSIGNED NOT NULL,registration_id INT UNSIGNED UNIQUE NOT NULL,team_name VARCHAR(80) NOT NULL,placement INT UNSIGNED NOT NULL DEFAULT 1,elimination_points INT UNSIGNED NOT NULL DEFAULT 0,placement_points INT UNSIGNED NOT NULL DEFAULT 0,total_points INT UNSIGNED NOT NULL DEFAULT 0,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(tournament_id) REFERENCES tournaments(tournament_id) ON DELETE CASCADE,FOREIGN KEY(registration_id) REFERENCES registrations(registration_id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE announcements(announcement_id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(180) NOT NULL,body TEXT NOT NULL,created_by INT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(created_by) REFERENCES admins(admin_id) ON DELETE SET NULL) ENGINE=InnoDB;
